import type { LicenseType, UserRow, UserStatus } from "./users-data";

/* ─────────────────────────────────────────────────────────────
 * THE PLANT WORKFORCE (13 Nov 2026)
 *
 * Caldwell Precision Manufacturing's people on the floor: 243 users across
 * five warehouses, the same people the Calendars and Shift Management
 * modules schedule. Those modules keep a byte-identical copy of this file
 * (calendar-omne `src/app/data/workforce-users.ts`), so a name clicked
 * there opens this user here, with the same email, licence, role and photo.
 * Edit it here and copy it across. It imports nothing but types, so the
 * copy needs no other UAC file; the user page's profile fields are built
 * from it in user-detail-data.ts.
 *
 * Generated once from the Shift Management roster, then kept as plain
 * data. The rules it follows, so a hand edit keeps them:
 *   • One role per user, the one their job needs; the licence is that
 *     role's tier (Field User for floor roles, Full Access for supervisors,
 *     leads, planners and quality engineers). Workforce users are never
 *     padded into other roles (uac-derived `padRoleMembership`).
 *   • Each site was brought onto Omne in a wave, invited by whoever ran it:
 *     Chicago Feb 2025 (Taylor Dimas), Dallas Apr 2025 (Dana Johansen),
 *     Long Beach May 2025 (Aden Erickson), Newark Oct 2025 and Atlanta
 *     Nov 2025 (Sophie Bergström). A later hire is invited a week before
 *     their first day by the site's HR Administrator at that time, and
 *     accepts on their first morning.
 *   • Status follows employment: working people are Active (on leave too);
 *     the two who left are Inactive, deactivated by HR on their last day;
 *     the four hires who have not started are Invite Sent; the one user
 *     created before their licence was bought is Pending Setup with No
 *     License.
 *   • Last logon is the clock-in before the user's shift on its calendar.
 *   • Supervisors, leads and Full Access users report to the operations
 *     manager (Ahtisham Ahmad); everyone else to their department's lead
 *     at their site, or the site's shift supervisor.
 *   • `avatarUrl` is a stock portrait, chosen so no face repeats on one
 *     shift's roster. Two of the 72 on Peak Season Fulfilment show initials.
 *   • `hiredOn` and `department` belong to employment, not access; UAC
 *     shows them as the job title and work location only. Shift Management
 *     reads them.
 * ───────────────────────────────────────────────────────────── */

export interface WorkforceUser {
  id: number;
  fullName: string;
  jobTitle: string;
  department: string;
  /** Home warehouse, by WH code. */
  warehouse: string;
  /** First day of employment, YYYY-MM-DD. */
  hiredOn: string;
  roleIds: number[];
  license: LicenseType;
  status: UserStatus;
  email: string;
  phone: string;
  invitedBy: string;
  invitedOn: string;
  inviteAcceptedOn: string;
  lastLogon: string;
  createdBy: string;
  lastEditedBy?: string;
  reportsTo: string;
  avatarUrl?: string;
}

