export function isWorkforceUserId(id: number): boolean {
  return id >= WORKFORCE_FIRST_ID;
}

/** The rows the Users listing reads. */
export function workforceUserRows(): UserRow[] {
  return WORKFORCE_USERS.map((w) => ({
    id: w.id,
    fullName: w.fullName,
    assignedRoles: [],
    license: w.license,
    email: w.email,
    phone: w.phone,
    lastLogon: w.lastLogon,
    status: w.status,
    invitedBy: w.invitedBy,
    invitedOn: w.invitedOn,
    inviteAcceptedOn: w.inviteAcceptedOn,
    createdBy: w.createdBy,
    ...(w.lastEditedBy ? { lastEditedBy: w.lastEditedBy } : {}),
  }));
}

/** Canonical role membership, merged into `USER_ROLE_IDS`. */
export const WORKFORCE_ROLE_IDS: Record<number, number[]> = Object.fromEntries(
  WORKFORCE_USERS.map((w) => [w.id, [...w.roleIds]]),
);

/** Photos, merged into `USER_AVATAR_MAP`. */
export const WORKFORCE_AVATARS: Record<number, string> = Object.fromEntries(
  WORKFORCE_USERS.filter((w) => w.avatarUrl).map((w) => [w.id, w.avatarUrl!]),
);

